const rates={USD:1,IDR:16000};let slide=0,filter='all';
renderLanguage();const PALMA_API_BASE =
  'https://palma-rotan-api-staging.hallo-palmarotancraft-id.workers.dev';
async function syncSettingsFromAPI() {
  try {
    const response = await fetch(`${PALMA_API_BASE}/api/settings`, {
      method: 'GET',
      headers: {
        'Accept': 'application/json'
      },
      cache: 'no-store'
    });

    if (!response.ok) return;

    const result = await response.json();

    if (result && result.settings) {
      const remote = result.settings;
      data.settings = {
        ...data.settings,
        ...remote
      };

      const homepage = remote.homepage;
      if (homepage) {
        if (homepage.taglineEN != null) data.taglineEN = homepage.taglineEN;
        if (homepage.taglineID != null) data.taglineID = homepage.taglineID;
        if (homepage.introEyebrowEN != null) data.introEyebrowEN = homepage.introEyebrowEN;
        if (homepage.introEyebrowID != null) data.introEyebrowID = homepage.introEyebrowID;
        if (homepage.showIntroEyebrow != null) data.showIntroEyebrow = homepage.showIntroEyebrow !== false;
        if (Array.isArray(homepage.hero)) {
          data.hero = homepage.hero.map(remoteHero => ({ ...remoteHero }));
        }
        if (Array.isArray(homepage.collections)) {
          data.collections = homepage.collections.map(remoteCollection => ({ ...remoteCollection }));
        }
        if (homepage.catalogSection) data.catalogSection={...(data.catalogSection||{}),...homepage.catalogSection};
        if (homepage.processSection) data.processSection={...(data.processSection||{}),...homepage.processSection};
        if (homepage.promoSection) data.promoSection={...(data.promoSection||{}),...homepage.promoSection}; if (homepage.journalSection) data.journalSection={...(data.journalSection||{}),...homepage.journalSection}; if (homepage.storySection) data.storySection={...(data.storySection||{}),...homepage.storySection}; if (homepage.wholesaleSection) data.wholesaleSection={...(data.wholesaleSection||{}),...homepage.wholesaleSection};
      }

      safeLocalSave();

      applyAppearance();
      renderLanguage();

      console.log(
        '[PALMA ROTAN] Settings berhasil disinkronkan dari API:',
        {
          hero: Array.isArray(data.hero) ? data.hero.length : 0,
          collections: Array.isArray(data.collections) ? data.collections.length : 0
        }
      );
    }
  } catch (error) {
    console.warn('Gagal sinkronisasi settings:', error);
  }
}
async function syncProductsFromAPI() {
  try {
    const response = await fetch(`${PALMA_API_BASE}/api/products`, {
      method: 'GET',
      headers: {
        'Accept': 'application/json'
      },
      cache: 'no-store'
    });

    if (!response.ok) {
      throw new Error(`Products API HTTP ${response.status}`);
    }

    const result = await response.json();

    if (!result || !Array.isArray(result.products)) {
      console.warn(
        '[PALMA ROTAN] Format API products tidak sesuai:',
        result
      );
      return;
    }

    const language = data.settings.language === 'ID' ? 'ID' : 'EN';

    data.products = result.products.map(p => {
      let image = '';

      if (p.image_key) {
        const key = String(p.image_key).trim();
        if (/^data:|^blob:|^https?:\/\//i.test(key)) {
          image = key;
        } else if (key.startsWith('assets/')) {
          image = normalizeAssetUrl(key);
        } else if (key.startsWith('media/')) {
          image = `${PALMA_API_BASE}/${key}`;
        } else {
          image = `${PALMA_API_BASE}/media/${key.replace(/^\/+/, '')}`;
        }
      } else if (p.image) {
        image = normalizeAssetUrl(p.image);
      }

      return {
        id: p.id,

        name: language === 'ID'
          ? (p.name_id || p.name_en || '')
          : (p.name_en || p.name_id || ''),

        type: p.type || 'Retail',
        category: p.category || 'all',

        price: Number(
          p.price_usd ?? p.price ?? 0
        ),

        stock: Number(p.stock ?? 0),

        moq: Number(p.moq ?? 1),

        prices: {
          IDR: Number(p.price_idr ?? 0),
          USD: Number(p.price_usd ?? p.price ?? 0)
        },

        image,

        description: language === 'ID'
          ? (p.description_id || p.description_en || '')
          : (p.description_en || p.description_id || ''),

        weight: Number(p.weight_kg ?? 0),

        dimensions: p.dimensions_cm || ''
      };
    });

    safeLocalSave();

    renderProducts();

    console.log(
      '[PALMA ROTAN] Produk berhasil disinkronkan dari D1:',
      data.products.length
    );

  } catch (error) {
    console.warn(
      '[PALMA ROTAN] Sinkronisasi produk API gagal:',
      error
    );
  }
}
function syncFromAdmin(){try{const raw=safeLocalLoad();if(!raw)return;const next=JSON.parse(raw);if(next&&next.settings){data=next;applyAppearance();renderLanguage()}}catch(e){console.warn('Appearance sync failed',e)}}
