function renderProducts(){const lang=data.settings.language==='ID'?'ID':'EN';const p=data.products.filter(x=>filter==='all'||x.category===filter);const labels=lang==='ID'?[['all','Semua'],['home','Dekorasi Rumah'],['vase','Vas & Pot'],['basket','Keranjang'],['gift','Hadiah']]:[['all','All'],['home','Home Decor'],['vase','Vase & Planter'],['basket','Baskets'],['gift','Gifts']];document.getElementById('filters').innerHTML=labels.map(([v,t])=>`<button class="${filter===v?'active':''}" onclick="setFilter('${v}')">${t}</button>`).join('');document.getElementById('products').innerHTML=p.map(x=>`<article class="product" onclick="productDetail('${x.id}')"><div class="productImg"><img src="${x.image}" alt="${x.name}"><button class="wish" aria-label="Wishlist" onclick="event.stopPropagation();toggleWish('${x.id}')">${wish().includes(x.id)?'♥':'♡'}</button></div><div class="productMeta"><small>${x.category}</small><h3>${x.name}</h3><p>${productMoney(x)}</p><div class="excludeNote">${lang==='ID'?'Belum termasuk ongkir':'Price excludes shipping'}</div></div></article>`).join('')||(lang==='ID'?'<p>Belum ada produk.</p>':'<p>No products.</p>');document.getElementById('cartCount').textContent=cart().reduce((a,x)=>a+x.qty,0);document.getElementById('wishCount').textContent=wish().length}
