function isCustom(p){return ['custom','wholesale','oem'].includes((p.type||'retail').toLowerCase())}function productDetail(id){const p=data.products.find(x=>x.id===id);if(!p)return;const lang=data.settings.language,isC=isCustom(p),min=isC?Math.max(1,p.moq||1):1;document.getElementById('drawerContent').innerHTML=`<span class="eyebrow">${p.category}</span><h2>${p.name}</h2><img src="${p.image}" style="width:100%;aspect-ratio:4/3;object-fit:cover"><p>${p.description}</p><p><b>${productMoney(p)}</b> · ${lang==='ID'?'Belum termasuk ongkir':'Price excludes shipping'}</p><p>${lang==='ID'?'Stok':'Stock'}: ${p.stock}${isC?` · MOQ: ${min}`:''}</p><label>Quantity</label><input id="detailQty" type="number" min="${min}" max="${p.stock}" value="${min}" style="width:100%;padding:12px;border:1px solid #ddd"><button class="btn dark" style="margin-top:15px;width:100%" onclick="addToCart('${p.id}',Number(document.getElementById('detailQty').value));closeDrawer()">${lang==='ID'?'Tambah ke Keranjang':'Add to Cart'}</button><button class="btn outline" style="margin-top:8px;width:100%" onclick="buyNow('${p.id}')">${lang==='ID'?'Beli Sekarang':'Buy Now'}</button>`;openDrawer()}
function addToCart(id,qty=1){const p=data.products.find(x=>x.id===id);if(!p)return false;const min=isCustom(p)?Math.max(1,p.moq||1):1;qty=Math.max(min,Math.floor(qty));if(qty>p.stock){toast(data.settings.language==='ID'?'Jumlah melebihi stok tersedia':'Quantity exceeds available stock');return false}let c=cart();const i=c.find(x=>x.id===id);if(i)i.qty=Math.min(p.stock,i.qty+qty);else c.push({id,qty});localStorage.setItem('palmaCart',JSON.stringify(c));renderProducts();toast(data.settings.language==='ID'?'Ditambahkan ke keranjang':'Added to cart');return true}
