async function createOrder(fd){
  const c=cart();
  const currency=data.settings.currency||'USD';
  for(const x of c){const p=data.products.find(p=>p.id===x.id);if(!p||x.qty<(isCustom(p)?Math.max(1,p.moq||1):1)||x.qty>p.stock){toast('Stock or MOQ changed. Please review cart.');openCart();return}}
  const shipping=shippingFee(fd.get('country'),fd.get('method'),currency);
  const api=(window.PALMA_COMMERCE_BASE||PALMA_API_BASE||'').replace(/\/$/,'');
  const commerceMode=!!(window.PALMA_COMMERCE_BASE||'').trim();
  if(api){
    try{
      const payload={
        currency,
        items:c.map(x=>{const p=data.products.find(p=>p.id===x.id);return {productId:x.id,sku:p?.sku||p?.sku_code||x.id,quantity:x.qty}}),
        shippingMethod:fd.get('method'),
        shippingAddress:{country:fd.get('country'),province:fd.get('province'),city:fd.get('city'),district:fd.get('district'),postalCode:fd.get('postalCode'),address:fd.get('address')},
        customer:{firstName:fd.get('name'),lastName:'',email:fd.get('email'),phone:fd.get('wa'),country:fd.get('country')},paymentMethod:fd.get('payment')||'gateway',paymentGateway:fd.get('payment')||'gateway'
      };
      const endpoint=commerceMode?api+'/wp-json/palma/v1/order':api+'/api/orders';
      const r=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});
      const j=await r.json().catch(()=>({}));
      if(!r.ok)throw new Error(j.error||'Order API gagal');
      localStorage.removeItem('palmaCart');
      const paymentUrl=j.paymentUrl||j.payment_url||j.redirectUrl||j.redirect_url||'';
      const paymentAction=paymentUrl?'<a class="btn dark" href="'+paymentUrl.replace(/"/g,'&quot;')+'" target="_blank" rel="noopener">'+(data.settings.language==='ID'?'Lanjut ke Pembayaran':'Continue to Payment')+'</a>':'';
      document.getElementById('drawerContent').innerHTML=`<h2>${data.settings.language==='ID'?'Pesanan':'Order'} ${j.orderNumber}</h2><div class="notice">${data.settings.language==='ID'?'Pesanan berhasil dibuat. Status pembayaran akan diperbarui otomatis oleh server.':'Order created. Payment status will be updated automatically by the server.'}</div><div class="summary"><div class="sum"><span>${data.settings.language==='ID'?'Produk':'Products'}</span><b>${moneyCurrency(j.subtotal,currency)}</b></div><div class="sum"><span>${data.settings.language==='ID'?'Ongkir':'Shipping'}</span><b>${moneyCurrency(Number(j.shippingAmount??shipping),currency)}</b></div><div class="sum total"><span>Total</span><b>${moneyCurrency(j.total,currency)}</b></div></div><p>${data.settings.language==='ID'?'Nilai dashboard Admin (IDR)':'Admin dashboard value (IDR)'}: <b>${moneyCurrency(j.adminTotalIdr,'IDR')}</b></p><p>Status: <b>NEW</b></p><div style="display:flex;gap:10px;flex-wrap:wrap">${paymentAction}<button class="btn dark" onclick="closeDrawer()">${data.settings.language==='ID'?'Tutup':'Close'}</button></div>`;
      renderProducts();toast('Order created');return;
    }catch(err){toast(err.message||'Order API gagal');return}
  }
  const subtotal=c.reduce((a,x)=>{const p=data.products.find(p=>p.id===x.id);return a+priceValue(p,currency)*x.qty},0),total=subtotal+shipping;
  const id='PR-'+new Date().getFullYear()+'-'+String(Date.now()).slice(-6);
  const payment=fd.get('payment')==='Bank Transfer'?'Menunggu Verifikasi':'Menunggu Pembayaran';
  const customer={first:fd.get('name'),last:'',email:fd.get('email'),country:fd.get('country'),whatsapp:fd.get('wa'),address:fd.get('address')};
  const order={id,created:new Date().toISOString(),currency,customer,items:c.map(x=>{const p=data.products.find(p=>p.id===x.id);return {id:p.id,name:p.name,price:priceValue(p,currency),qty:x.qty}}),subtotal,shipping,total,paymentMethod:fd.get('payment'),paymentStatus:payment,orderStatus:'MENUNGGU PEMBAYARAN',stockReserved:false,automationLog:['Order dibuat otomatis']};
  data.orders.unshift(order);let cu=data.customers.find(x=>x.email===customer.email);if(!cu){cu={name:customer.first,email:customer.email,country:customer.country,orders:0};data.customers.push(cu)}cu.orders++;save();localStorage.removeItem('palmaCart');
  document.getElementById('drawerContent').innerHTML=`<h2>${data.settings.language==='ID'?'Pesanan':'Order'} ${id}</h2><div class="notice">${payment==='Menunggu Verifikasi'?(data.settings.language==='ID'?'Bukti pembayaran akan diverifikasi admin sebelum stok diproses.':'Payment proof will be reviewed before stock is processed.'):(data.settings.language==='ID'?'Silakan selesaikan pembayaran untuk melanjutkan pesanan.':'Please complete payment to continue the order.')}</div><div class="summary"><div class="sum"><span>Products</span><b>${money(subtotal)}</b></div><div class="sum"><span>Shipping</span><b>${money(shipping)}</b></div><div class="sum total"><span>Total</span><b>${money(total)}</b></div></div><p>Status: <b>${order.orderStatus}</b></p><button class="btn dark" onclick="closeDrawer()">Close</button>`;renderProducts();toast('Order created automatically');
}
function openWishlist(){const w=wish();document.getElementById('drawerContent').innerHTML=`<h2>Wishlist</h2>${w.map(id=>{const p=data.products.find(x=>x.id===id);return p?`<div class="cartRow"><img src="${p.image}"><div><h4>${p.name}</h4><p>${productMoney(p)}</p></div><button class="btn" onclick="addToCart('${p.id}');openWishlist()">Add</button></div>`:''}).join('')||'<p>Wishlist is empty.</p>'}`;openDrawer()}
function openSearch(){const q=prompt('Search products');if(!q)return;const found=data.products.filter(p=>p.name.toLowerCase().includes(q.toLowerCase()));toast(found.length?`${found.length} product(s) found`:'No product found');if(found.length){filter='all';document.getElementById('shop').scrollIntoView();}}
function openDrawer(){document.getElementById('drawer').classList.add('open')}function closeDrawer(){document.getElementById('drawer').classList.remove('open')}function toggleNav(){document.getElementById('nav').style.display=document.getElementById('nav').style.display==='flex'?'none':'flex'}function toggleLanguage(){data.settings.language=data.settings.language==='ID'?'EN':'ID';save();renderLanguage()}function cycleCurrency(){const cs=['USD','IDR'];const i=cs.indexOf(data.settings.currency);data.settings.currency=cs[(i+1)%cs.length];save();renderLanguage();renderProducts()}
document.getElementById('quoteForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);data.quotes.unshift({id:'Q-'+Date.now(),created:new Date().toISOString(),name:fd.get('name'),email:fd.get('email'),country:fd.get('country'),qty:fd.get('qty'),message:fd.get('message'),status:'NEW'});save();e.target.reset();toast(data.settings.language==='ID'?'Permintaan penawaran berhasil dikirim':'Quote request submitted')};
function initScrollMotion(){const els=document.querySelectorAll('.reveal,.reveal-group');els.forEach(e=>e.classList.add('reveal-ready'));if(!('IntersectionObserver' in window)){els.forEach(e=>e.classList.add('is-visible'));document.querySelectorAll('.reveal-item').forEach(e=>e.classList.add('is-visible'));return}const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{entry.target.classList.toggle('is-visible',entry.isIntersecting);if(entry.isIntersecting&&entry.target.classList.contains('reveal-group'))entry.target.querySelectorAll('.reveal-item').forEach((el)=>el.classList.add('is-visible'));else if(!entry.isIntersecting&&entry.target.classList.contains('reveal-group'))entry.target.querySelectorAll('.reveal-item').forEach((el)=>el.classList.remove('is-visible'))})},{threshold:.14,rootMargin:'0px 0px -8% 0px'});els.forEach(e=>observer.observe(e))}
renderLanguage();initScrollMotion();document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',()=>{const id=a.getAttribute('href');if(!id||id==='#')return;const target=document.querySelector(id);if(target){target.classList.add('is-visible');target.querySelectorAll('.reveal-item').forEach(x=>x.classList.add('is-visible'))}}));syncSettingsFromAPI();syncProductsFromAPI();
